// qa (2 Nov, after-merge on main d98041e7, #572 QA-165 part 1): C7.2 through the upload endpoint, not the reader alone.
// (1) an IMM 5257 copy uploaded without Validate (the generated bytes, or bytes appended) is never "validated";
// (2) a copy validated by the form's own flag is. P-171 (1) (out of date after a later change) needs a case with confirmed
// facts on the copy (a fresh case writes 0 values), so it is not checked here.
// No browser, NO model call (US$0).
//   zsh studio/tools/isolated.sh qa_c72v 4471 start && tsx studio/tests/runtime/setup_visitor_visa.ts 4471 xr_studio_qa_c72v \
//     && tsx studio/tests/qa/check_qa_c72_validated_upload.ts 4471 xr_studio_qa_c72v
import { adobeValidated } from "../runtime/validated.ts";
import { client, recorder } from "../runtime/api.ts";

const PORT = Number(process.argv[2] ?? 4471), DB = process.argv[3] ?? "xr_studio_qa_c72v";
const { call, sql, until } = client(PORT, DB);
const { ok, summary } = recorder();
const OFFICER = "user-O", CLIENT = "user-P";

const upload = async (copy: string, bytes: Buffer) => {
  const fd = new FormData(); fd.append("file", new Blob([new Uint8Array(bytes)]), "imm5257.pdf");
  const res = await fetch(`http://127.0.0.1:${PORT}/api/runtime/form-copies/${copy}/validated`, { method: "POST", headers: { "x-actor": OFFICER }, body: fd });
  return { status: res.status, body: await res.json().catch(() => null) as any }; // eslint-disable-line @typescript-eslint/no-explicit-any
};
const generate = async (caseId: string, P: string) => {
  const g = await call("POST", `/runtime/cases/${caseId}/forms/IMM%205257/${P}/generate`, { idempotencyKey: `qa-c72v-${Date.now()}-${Math.random()}` }, OFFICER);
  const copy = String(g.body?.copy?.id ?? g.body?.id ?? "");
  await until(async () => ["GENERATED", "FAILED"].includes((await call("GET", `/runtime/form-copies/${copy}`, undefined, OFFICER)).body?.status), 90_000);
  const dl = await fetch(`http://127.0.0.1:${PORT}/api/runtime/form-copies/${copy}/file?original=1`, { headers: { "x-actor": OFFICER } });
  return { copy, pdf: Buffer.from(await dl.arrayBuffer()) };
};

(async () => {
  const vv = sql(`select id from combination where combination_key = 'vv.single'`);
  if (!vv) { console.error("STOP  run tests/runtime/setup_visitor_visa.ts first"); process.exit(2); }
  const c = await call("POST", "/runtime/cases", { combinationId: vv, reference: `QA-C72V-${Date.now().toString(36)}`, clientActor: CLIENT, principal: { displayName: "Sample Applicant A" } }, OFFICER);
  const caseId = c.body?.id ?? c.body?.case?.id;
  const P = (await call("GET", `/runtime/cases/${caseId}`, undefined, OFFICER)).body?.people?.find((p: { role: string }) => p.role === "principal")?.subject_id;
  ok("setup: a Visitor visa case with its principal", !!caseId && !!P, c.body);

  let g = await generate(caseId, P);
  let up = await upload(g.copy, g.pdf);
  ok("fail (QA-165): the generated copy uploaded unchanged (Validate never pressed) is not validated, in words", up.body?.copy?.validated?.current !== true && /Validate/.test(JSON.stringify(up.body ?? "")), { status: up.status, validated: up.body?.copy?.validated });

  g = await generate(caseId, P);
  up = await upload(g.copy, Buffer.concat([g.pdf, Buffer.from("\n% bytes appended, no Validate\n")]));
  ok("fail (QA-165): bytes appended with no Validate result of the form's own is not validated", up.body?.copy?.validated?.current !== true, { status: up.status, validated: up.body?.copy?.validated });

  g = await generate(caseId, P);
  up = await upload(g.copy, adobeValidated(g.pdf));
  ok("pass: a copy whose own Validate flag says Yes (with its date) and whose barcodes agree with its answers (BK-19, P-46) is validated", up.status < 300 && up.body?.copy?.validated?.current === true, { status: up.status, validated: up.body?.copy?.validated });

  process.exit(summary() ? 1 : 0);
})().catch((e) => { console.error(e); process.exit(1); });
